create schema if not exists ged;
create extension if not exists pgcrypto;
create table if not exists ged.archive_work_order (id uuid primary key default gen_random_uuid(),tenant_id uuid not null,order_number varchar(40) not null,title text not null,description text null,order_type varchar(60) not null,priority varchar(30) not null default 'MEDIUM',status varchar(40) not null default 'OPEN',subject_type varchar(40),subject_id uuid,box_id uuid,document_id uuid,control_number text,location_expected text,location_found text,location_target text,source_type varchar(60),source_id uuid,assigned_to uuid,assigned_by uuid,assigned_at timestamptz,due_at timestamptz,started_at timestamptz,completed_at timestamptz,completed_by uuid,closed_at timestamptz,closed_by uuid,close_notes text,cancellation_reason text,created_by uuid,created_at timestamptz not null default now(),updated_by uuid,updated_at timestamptz,reg_status char(1) not null default 'A');
create table if not exists ged.archive_work_order_task (id uuid primary key default gen_random_uuid(),tenant_id uuid not null,work_order_id uuid not null references ged.archive_work_order(id),title text not null,description text,task_type varchar(60) not null,status varchar(40) not null default 'PENDING',display_order integer not null default 0,requires_scan boolean not null default false,requires_evidence boolean not null default false,assigned_to uuid,started_at timestamptz,completed_at timestamptz,completed_by uuid,result_notes text,payload_json jsonb,reg_status char(1) not null default 'A');
create table if not exists ged.archive_work_order_event (id uuid primary key default gen_random_uuid(),tenant_id uuid not null,work_order_id uuid not null references ged.archive_work_order(id),task_id uuid references ged.archive_work_order_task(id),event_type varchar(60) not null,event_title text not null,event_description text,from_status varchar(40),to_status varchar(40),performed_by uuid,performed_at timestamptz not null default now(),ip_address inet,user_agent text,payload_json jsonb,reg_status char(1) not null default 'A');
create table if not exists ged.archive_work_order_evidence (id uuid primary key default gen_random_uuid(),tenant_id uuid not null,work_order_id uuid not null references ged.archive_work_order(id),task_id uuid references ged.archive_work_order_task(id),label_evidence_id uuid,description text,attached_by uuid,attached_at timestamptz not null default now(),reg_status char(1) not null default 'A');
create unique index if not exists ux_archive_work_order_tenant_number on ged.archive_work_order(tenant_id,order_number);
create index if not exists ix_archive_work_order_status on ged.archive_work_order(tenant_id,status,priority,due_at); create index if not exists ix_archive_work_order_assigned on ged.archive_work_order(tenant_id,assigned_to,status,due_at); create index if not exists ix_archive_work_order_subject on ged.archive_work_order(tenant_id,subject_type,subject_id); create index if not exists ix_archive_work_order_source on ged.archive_work_order(tenant_id,source_type,source_id); create index if not exists ix_archive_work_order_task_order on ged.archive_work_order_task(tenant_id,work_order_id,display_order); create index if not exists ix_archive_work_order_event_order on ged.archive_work_order_event(tenant_id,work_order_id,performed_at desc);
